<!doctype html><html lang="vi"><head><meta charset="UTF-8"><style>body{font-family:"DejaVu Sans",sans-serif;font-size:11px;color:#182235}h1{font-size:24px;color:#163f62}h2{border-bottom:1px solid #cad4df;padding-bottom:5px;margin-top:20px}.muted{color:#52657a}p{line-height:1.5}<?php if(($cv['templateId']??'classic')==='modern'): ?>body{border-top:6px solid #2563eb;padding-top:16px}h1,h2{color:#2563eb}<?php elseif(($cv['templateId']??'classic')==='minimal'): ?>h1,h2{color:#182235}h2{border:0;text-transform:uppercase;font-size:12px;letter-spacing:1px}<?php endif; ?></style></head><body>
<h1><?= e($data['fullName']??'CV') ?></h1><p class="muted"><?= e($data['headline']??'') ?></p>
<p><?= e(($data['email']??'').' · '.($data['phone']??'').' · '.($data['location']??'')) ?></p><p><?= nl2br(e($data['summary']??'')) ?></p>
